#include <stdio.h>

double num(double a[], int n)
{
    double avg = 0.0;
    int i, k = 0;

    for (i = 0; i < n; i++)          /* 求所有元素的平均值 */
        avg += a[i];
    avg /= n;
    for (i = 0; i < n; i++) {        /* 升序：最后一个 <=avg 的元素即最接近且 <=avg */
        if (a[i] <= avg)
            k = i;
        else
            break;
    }
    return a[k];
}

