```c
#include <stdio.h>

int isPassword(char *s)
{
    int len = 0, i, upper = 0, lower = 0, digit = 0;

    while (s[len] != '\0')              /* 手工计算长度，不调用库函数 */
        len++;
    if (len < 8 || len > 15)            /* 长度不符 */
        return -1;
    for (i = 0; i < len; i++) {         /* 检查三类字符是否至少各出现一次 */
        if (s[i] >= 'A' && s[i] <= 'Z')
            upper = 1;
        else if (s[i] >= 'a' && s[i] <= 'z')
            lower = 1;
        else if (s[i] >= '0' && s[i] <= '9')
            digit = 1;
    }
    if (upper == 1 && lower == 1 && digit == 1)
        return 1;
    return 0;
}

int main(void)
{
    printf("%d\n", isPassword("Abcdefg1"));      /* 1 */
    printf("%d\n", isPassword("abcdefg1"));      /* 0：无大写字母 */
    printf("%d\n", isPassword("Abcdefgh"));      /* 0：无数字 */
    printf("%d\n", isPassword("Ab1"));           /* -1：长度不足 */
    return 0;
}
