answer.md:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
struct student {
    char num[11];
    char name[20];
    int score;
    struct student *next;
};
int ustrcmp(char *a, char *b);
struct student *SortInsert(struct student *head, struct student *ps);

int ustrcmp(char *a, char *b)               /* 按 ASCII 码顺序比较字符串 */
{
    while (*a != '\0' && *a == *b) {
        a++;
        b++;
    }
    return *a - *b;
}

struct student *SortInsert(struct student *head, struct student *ps)
{
    struct student *p;

    if (head == NULL || ustrcmp(ps->num, head->num) < 0) {
        ps->next = head;                    /* 空表或学号最小：插在表头 */
        head = ps;
        return head;
    }
    p = head;
    while (p->next != NULL && ustrcmp(ps->num, p->next->num) >= 0)
        p = p->next;                        /* 找第一个学号比新结点大的结点 */
    ps->next = p->next;
    p->next = ps;
    return head;
}

int main()
{
    struct student s, *ps = NULL, *head = NULL;
    FILE *fp;

    scanf("%s", s.num);
    while (strcmp(s.num, "0") != 0) {       /* 学号为 "0" 结束输入 */
        scanf("%s%d", s.name, &s.score);
        ps = (struct student *)malloc(sizeof(struct student));
        *ps = s;                            /* 每条信息创建一个新结点 */
        head = SortInsert(head, ps);
        scanf("%s", s.num);
    }
    fp = fopen("d:\\temp\\grade.dat", "w");
    if (fp == NULL) {
        printf("cannot open file\n");
        return 1;
    }
    for (ps = head; ps != NULL; ps = ps->next)
        fprintf(fp, "%s %s %d\n", ps->num, ps->name, ps->score);
    fclose(fp);
    return 0;
}
```

