long catalan(int n)
{
    int i;
    long sum = 0;
    if (n <= 1) return 1;   /* 递归出口：c(0)=c(1)=1 */
    for (i = 0; i < n; i++) /* c(n) = Σ c(i)*c(n-1-i), i=0..n-1 */
        sum += catalan(i) * catalan(n - 1 - i);
    return sum;
}

int main()
