struct  Grade_Info
{
  int  score;
  struct  Grade_Info  *next;
};
typedef  struct  Grade_Info  NODE;
NODE *Create_LinkList( )；//已经定义和实现好，可以直接调用

answer.md:
```c
#include <stdio.h>

struct Grade_Info
{
  int  score;
  struct Grade_Info  *next;
};
typedef struct Grade_Info NODE;
```

NODE *Create_LinkList(void);   /* 题目已定义和实现，可直接调用 */

/* 合并两个 score 升序的链表，返回合并后的链表头指针 */
NODE *merge(NODE *h1, NODE *h2)
{
    NODE  head;                /* 哑结点，便于处理头结点 */
    NODE *tail = &head;
    head.next = NULL;
    while (h1 != NULL && h2 != NULL)
    {
        if (h1->score <= h2->score)
        { tail->next = h1;  h1 = h1->next; }
        else
        { tail->next = h2;  h2 = h2->next; }
        tail = tail->next;
    }
    tail->next = (h1 != NULL) ? h1 : h2;   /* 接上剩余结点 */
    return head.next;
}

/* 将链表中各结点的 score 保存到文件 score.data */

```c
void save(NODE *head)
{
    FILE *fp;
    NODE *p;
    fp = fopen("score.data", "w");
    if (fp == NULL)
    {
        printf("cannot open score.data\n");
        return;
    }
    for (p = head; p != NULL; p = p->next)
        fprintf(fp, "%d\n", p->score);
    fclose(fp);
}

int main()
{
    NODE *la, *lb, *lc;
    la = Create_LinkList();
    lb = Create_LinkList();
    lc = merge(la, lb);
    save(lc);
    return 0;
}
```

