```c
int readdata(char *fname, int d[]) {
    //将文件 fname 中的数据读入数组 d 中并返回数据个数
    //打开文件失败，或未能从文件中读取数据时返回 0
    FILE *fp;
    int cnt = 0;
    if (!(fp = fopen(fname, "r"))) return 0;
    while (fscanf(fp, "%d", d) != EOF) ++d, ++cnt;
    fclose(fp);
    return cnt;
}

int median(int d[], int n) {  //返回中位数
    //用冒泡法对数组 d 中的 n 个数据排序，如果数据个数是奇数，则中间那个数据是中位数；
    //如果数据个数是偶数，则中间那 2 个数据的算术平均值取整是中位数.
    for (int i = 0; i < n-1; ++i)
        for (int j = 0; j < n-1-i; ++j)
            if (d[j] > d[j+1]) {
                int t = d[j];
                d[j] = d[j+1];
                d[j+1] = t;
            }
    if (n % 2 == 1) return d[n/2];
    else return (d[n/2-1] + d[n/2]) / 2;
}
```

