#include <stdio.h>
#define N1  3
#define N5  3
#define N20 5
#define N50 4

int main(void)
{
    int price;
    int a, b, c, d;                 /* 50/20/5/1 元纸币张数 */
    int best = -1, ba = 0, bb = 0, bc = 0, bd = 0;

    scanf("%d", &price);

    for (a = 0; a <= N50; a++)               /* 枚举 50 元张数 */
        for (b = 0; b <= N20; b++)           /* 枚举 20 元张数 */
            for (c = 0; c <= N5; c++) {      /* 枚举 5 元张数，1 元张数随之确定 */
                d = price - a * 50 - b * 20 - c * 5;
                if (d >= 0 && d <= N1) {     /* 1 元张数合法即恰好付清 */
                    int cnt = a + b + c + d;
                    if (best == -1 || cnt < best) {
                        best = cnt; ba = a; bb = b; bc = c; bd = d;
                    }
                }
            }

    if (best == -1)
        printf("无法支付！\n");
    else
        printf("最少需要%d张，其中50元%d张，20元%d张，5元%d张，1元%d张\n",
               best, ba, bb, bc, bd);
    return 0;
}
