void replace(char *src, char dest[], char *sub, char *word)
{
    int lw = (int)strlen(word);         /* word 的长度 */
    int ls = (int)strlen(sub);          /* sub 的长度 */
    char buf[11];                       /* 暂存 src 中待比较的 lw 个字符，lw<=10 */
    int i = 0, j = 0;                   /* i 扫描 src，j 为 dest 写入位置 */

    while (src[i] != '\0') {
        strncpy(buf, src + i, lw);      /* 取 src 从 i 起的 lw 个字符 */
        buf[lw] = '\0';
        if (strcmp(buf, word) == 0) {   /* 匹配到 word：写入 sub */
            strcpy(dest + j, sub);
            j += ls;
            i += lw;
        } else {                        /* 不匹配：原样复制一个字符 */
            dest[j++] = src[i++];
        }
    }
    dest[j] = '\0';
}
