link *initlink(int num)
{
        link *head = (link *)malloc(sizeof(link));
        head->next=NULL;
        link *tmp = head;
        for (int i = 0; i < num; i++)
        {
                tmp=(link*)malloc(sizeof(link));
                tmp->next = head->next;
                head->next=tmp;
                scanf("%c", &(tmp->c));
        }
        return head;
}
link *reverselink(link *L)
{
        link *p;
        p = L->next;
        L->next = NULL;
        while (p != NULL)
        {
                link *tmp;
                tmp = p->next;
                p->next = L->next;
                L->next = p;
                p = tmp;
        }
        return L;
}

