    // 读取两个单词
    scanf("%s%s", word1, word2);

    int len1 = strlen(word1);
    int len2 = strlen(word2);

    // 从最大可能的重合长度开始尝试（取两个单词长度的较小值）
    int max_possible = (len1 < len2) ? len1 : len2;

    // 尝试不同的重合长度（从大到小，找到最大的有效重合）
    for (int overlap_len = max_possible; overlap_len > 0; overlap_len--) {
        int match = 1;  // 假设匹配

        // 比较word1的末尾overlap_len个字符与word2的开头overlap_len个字符
        for (int i = 0; i < overlap_len; i++) {
            if (word1[len1 - overlap_len + i] != word2[i]) {
                match = 0;  // 发现不匹配的字符
                break;
            }
        }

        // 如果匹配成功
        if (match) {
            // 将重合部分复制到overlap数组中
            for (int i = 0; i < overlap_len; i++) {
                overlap[i] = word2[i];
            }
            overlap[overlap_len] = '\0';  // 添加字符串结束符
            found = 1;
            break;  // 找到最大重合部分，退出循环
        }
    }

    // 输出结果
    if (found) {
