void merge(int a[], int b[], int c[], int m, int n) {
        int i=0, j=0, k=0;
        while(i<m && j<n) {
                if(a[i]<=b[j]) {
                        c[k]=a[i];
                        i++;
                        k++;
                }
                else {
                        c[k]=b[j];
                        j++;
                        k++;
                }
                if(i==m) {
