// Insert a node into the linked list.
struct node *InsertList(struct node *head, struct node *q)
{
    struct node *p;

    if (!head) {
        q->next=head;
        head=q;
        return head;
        }

    if (head->num > q->num) {
        q->next = head;
        head = q;
        return head;
        }

    p = head;
    while (p->next && p->next->num < q->num)
        p = p->next;

    q->next = p->next;
    p->next = q;

    return head;
}

