```c
#include <stdio.h>
#include <string.h>

// 字符串压缩函数
void compressString(char input[], char output[]) {
    int len = strlen(input);
    int outputIndex = 0;
    int i = 0;

    while(i < len) {
        char currentChar = input[i];
        int count = 1;

        // 统计连续相同字符的数量
        while(i + count < len && input[i + count] == currentChar) {
            count++;
        }

        // 将字符和计数写入输出数组
        output[outputIndex++] = currentChar;

        // 如果计数大于1，添加数字
        if(count > 1) {
            // 将数字转换为字符串
            char countStr[10];
            int numLen = 0;
            int temp = count;

            // 计算数字位数
            while(temp > 0) {
                numLen++;
                temp /= 10;
            }

            // 将数字转换为字符串（逆序）
            temp = count;
            for(int j = numLen - 1; j >= 0; j--) {
                countStr[j] = '0' + (temp % 10);
                temp /= 10;
            }
            countStr[numLen] = '\0';

            // 复制数字到输出
            for(int j = 0; j < numLen; j++) {
                output[outputIndex++] = countStr[j];
            }
        }

        i += count;  // 移动到下一个不同字符
    }

    output[outputIndex] = '\0';  // 添加字符串结束符

    // 如果压缩后没有变短，返回原字符串
    if(outputIndex >= len) {
        strcpy(output, input);
    }
}

int main() {
    char input[101];    // 最多100个字符 + 结束符
    char output[201];   // 压缩后可能更长

    // 输入字符串
    // printf("请输入字符串：");
    scanf("%100s", input);  // 限制输入长度

    // 调用压缩函数
    compressString(input, output);

    // 输出结果
    // 原字符串：
    printf("%s\n", input);
    // 压缩结果：
    printf("%s", output);

    return 0;
}
