char *udf_gets(char s[], int lim)
{
    int c, i;
    for(i = 0; i < lim - 1 && (c = getchar()) != EOF && c!= '\n'; ++i) {
        s[i] = c;
    }
    s[i] = '\0';
}

int udf_strlen(char s[])
{
    int i = 0;
    while (s[i] != '\0') {
        i++;
    }
    return i;
}

int udf_strcmp(char s[], char t[])
{
    int i = 0;
    while (s[i] == t[i]) {
        if (s[i++] == '\0') {
            return 0;
        }
    }
    return (s[i] - t[i]);
}
