(1) 算法描述
head <= NULL;  // 置空链表
输入一个循环控制数据;
while(数据值不是结束标志) {
    申请新结点，用指针 p 指向该结点;
    给新结点赋予相关数据值;
    if(链表为空) {
        表示新插入的结点是首结点，
        头指针指向首结点 head <= p;
    } else {
        将新结点插入到尾指针指向的结点之后，rear->next <= p;
        使尾指针指向新结点，rear <= p;
    }
    输入一个循环控制数据;
}

函数定义：

```c
struct person *CreateListR(void)
{
    struct person *head;      // 头指针
    struct person *rear;      // 尾指针
    struct person *p;         // 新结点指针
    head = NULL;
    p = (struct person*)malloc(sizeof(struct person));   // 申请新结点
    printf("\n输入一个职工的工号和工资");
    scanf("%d%f", &p->no, &p->salary);
    while (p->no != 0) {   // 读入职工号不是结束标志(0)时做循环
        if (head == NULL) {
            head = p;         // 将 p 指向的新结点插入空表
        } else {
            rear->next = p;   // 新结点插入到表尾结点(rear 指向的结点)之后
        }
        rear = p;             // 表尾指针指向新的表尾结点
        p = (struct person*)malloc(sizeof(struct person)); // 申请新结点
        printf("\n输入一个职工的工号和工资");
        scanf("%d%f", &p->no, &p->salary);
    }
    rear->next = NULL;        // 终端结点置空
    free(p);
    return head;              // 返回表头指针
}
```

