void replace(char *src, char dest[], char *sub, char *word)
{
    int i,j,k,len_src,len_sub,len_word;
    char tmp[100];  //用于存放从 src 的下标 i 开始，与 word 等长子串
    i=0;  //用 i 扫 src 串
    k=0;  //用 k 扫 dest 串
    len_src=strlen(src);
    len_sub=strlen(sub);
    len_word=strlen(word);
    while(i<len_src)  {
        for(j=0;j<len_word;j++)  {  //从 src 串的下标 i 开始，取与 word 等长子串
            tmp[j]=src[i+j];
        }
        tmp[j]='\0';
        if(strcmp(tmp,word)==0)  {  //匹配上，直接将 sub 复制到 dest
            strcpy(dest+k,sub);
            i+=len_word;
            k+=len_sub;
        } else  {  //没匹配上，将 src[i] 复制到 dest
