    rear->next=NULL;          //终端结点置空
    free(p);
    return head;              //返回表头指针
}
```

编程要求(2)：编写将链表的职工信息写入 person_list.txt 文件的函数。
函数定义：

```c
void writListR(struct person * head){
    FILE * fp;
    struct person * p ;
    if((fp=fopen("person_list.txt","w"))==NULL){
        printf("cannot open this file. \n");
        exit(0);
    }
    p=head;
    while(p!=NULL){
        fprintf(fp,"%d %f\n", p->no,p->salary);
        p=p->next;
    }
}
