int maxProfit(int* prices, int pricesSize)
{
    if(pricesSize == 0 || pricesSize == 1)return 0;
    int buy[pricesSize];                    //第i天呈买的状态手里最大值
    int sell[pricesSize];                   //第i天呈卖的状态手里最大值
    memset(buy, 0, sizeof(int) * pricesSize);
    memset(sell, 0, sizeof(int) * pricesSize);

    buy[0] = -prices[0];        //第0天买了手里最大值
    sell[0] = 0;                //第0天卖没有意义
    buy[1] = fmax(-prices[0], -prices[1]);   //第一天买手里最大
    sell[1] = fmax(sell[0], buy[0] + prices[1]);
    for(int i = 2; i < pricesSize; i++)
    {
        buy[i] = fmax(buy[i-1], sell[i-2] - prices[i]);// (延续前一天) 或 (冷却一天后买)
        sell[i] = fmax(sell[i-1], buy[i-1] + prices[i]);// (延续前一天) 或 (手里股票昨天有, 今天卖了)
    }
    int res = INT_MIN;
    for(int i = 0; i < pricesSize; i++)
    {
        res = fmax(res, sell[i]);    //不用管买卖次数, 选利润最大的
    }

    return res;
}
