    int i, res;
    printf("请输入一个整数: ");
    scanf("%d", &i);  // 输入一个整数到i

    // 第一个表达式：如果i为0，则i自增1；否则i不变。
    // 当i为0时，!i为真(1)，继续计算&&右边，++i使i变为1。res结果为 1 && 1 -> 1。
    // 当i不为0时，!i为假(0)，&&发生短路，右边不计算，i不变。res结果为 0。
    res = !i && ++i;
    printf("&&=%d,i=%d\n", res, i);

    // 第二个表达式：如果i不为1，则i自减1；否则i不变。
    // 当i不为1时，(i!=1)为真(1)，继续计算&&右边，--i使i减1。res结果为 1 && (非零) -> 1。
    // 当i为1时，(i!=1)为假(0)，&&发生短路，右边不计算，i不变。res结果为 0。
    res = (i != 1) && --i;
    printf("||=%d,i=%d\n", res, i);

    // 第三个表达式：i为1或2，或res为0时，结果为1。
    // 这是一个纯逻辑判断，将条件直接用逻辑或||连接起来即可。
    res = (i == 1) || (i == 2) || (res == 0);
    printf("res=%d\n", res);

