void find_max_overlap(const char *a, const char *b, char *overlap) {
    int len_a = strlen(a);
    int len_b = strlen(b);
    int max_possible = len_a < len_b ? len_a : len_b;  // 最大可能重叠长度

    // 从大到小尝试所有可能的重叠长度
    for (int k = max_possible; k > 0; k--) {
        int match = 1;  // 假设匹配
        // 比较 a 的后 k 个字符与 b 的前 k 个字符
        for (int i = 0; i < k; i++) {
            if (a[len_a - k + i] != b[i]) {
                match = 0;  // 出现不匹配字符
                break;
            }
        }
        if (match) {
            // 找到最大重叠，复制到 overlap
            strncpy(overlap, a + len_a - k, k);
            overlap[k] = '\0';  // 确保字符串结束
            return;
        }
    }
    // 没有找到任何重叠
    overlap[0] = '\0';
}
