    for(i = 0; i < 4; i++)
        p[i] = a[i];    // p[i] 指向 a[i] 的首地址

    change(p, 4);

    for(i = 0; i < 4; i++)
        for(j = 0; j < 4; j++)
            printf("%2d%c", *(p[i] + j), j<3 ? ' ' : '\n');
}
